public String counterGame(long n) {
    int moves = 0;
    while (n > 1) {
        if ((n & (n - 1)) == 0) {        // power of 2 → single set bit
            n >>= 1;                     // halve
        } else {
            n -= Long.highestOneBit(n);  // subtract largest power of 2 below n
        }
        moves++;
    }
    return (moves % 2 == 1) ? "Louise" : "Richard";
}

code.python:
def counterGame(n: int) -> str:
    moves = 0
    while n > 1:
        if n & (n - 1) == 0:             # power of 2 → single set bit
            n >>= 1                       # halve
        else:
            n -= 1 << (n.bit_length() - 1)  # subtract largest power of 2 below n
        moves += 1
    return "Louise" if moves % 2 == 1 else "Richard"

