public String counterGame(long n) {
    int moves;
    if (n == 1) {
        moves = 0;
    } else {
        moves = (Long.bitCount(n) - 1) + Long.numberOfTrailingZeros(n);
    }
    return (moves % 2 == 1) ? "Louise" : "Richard";
}

code.python:
def counterGame(n: int) -> str:
    if n == 1:
        moves = 0
    else:
        popcount = bin(n).count("1")
        trailing = (n & -n).bit_length() - 1   # index of lowest set bit
        moves = (popcount - 1) + trailing
    return "Louise" if moves % 2 == 1 else "Richard"
